using System.Diagnostics;
using System.Text.Json;

namespace AcroFunJam.Infrastructure.Tests.Videos;

/// <summary>
/// The video files of the integration tests (ADR 0041), generated by ffmpeg during the test, once, in a cache of the temporary
/// directory: no binary file is versioned. A test pattern (<c>testsrc2</c>) with a sound (<c>sine</c>). Without ffmpeg, the tests
/// that need it are skipped with an explicit message; in the CI (<c>CI=true</c>, job <c>api</c>, where ffmpeg is installed), they
/// fail instead: a missing ffmpeg never passes unnoticed.
/// </summary>
internal static class TestVideoFixtures
{
    private static readonly string Cache = Path.Combine(Path.GetTempPath(), "acrofunjam-video-fixtures-v2");
    private static readonly SemaphoreSlim OneAtATime = new(1, 1);

    public static readonly bool FfmpegInstalled = Runs("ffmpeg") && Runs("ffprobe");

    public static void SkipWithoutFfmpeg()
    {
        const string Missing = "ffmpeg et ffprobe sont introuvables : installe ffmpeg (winget install ffmpeg, apt-get install ffmpeg) pour ces tests.";
        if (!FfmpegInstalled && string.Equals(Environment.GetEnvironmentVariable("CI"), "true", StringComparison.OrdinalIgnoreCase)) Assert.Fail(Missing);
        Assert.SkipUnless(FfmpegInstalled, Missing);
    }

    /// <summary>An MP4 H.264 of this many seconds and size, with a sound.</summary>
    public static Task<string> Mp4(double seconds, int width = 854, int height = 480) =>
        Generated($"mp4-{seconds}s-{width}x{height}.mp4",
            [.. Sources(seconds, width, height), "-c:v", "libx264", "-preset", "ultrafast", "-pix_fmt", "yuv420p", "-c:a", "aac", "-shortest"]);

    /// <summary>
    /// A MOV HEVC as an iPhone films it: a sound, a GPS position and the model of the device in the metadata, and the mark « rotate
    /// by 90° » (filmed in portrait).
    /// </summary>
    public static Task<string> IPhoneMov() =>
        Generated("iphone-hevc-rotated.mov",
        [
            .. Sources(12, 854, 480), "-c:v", "libx265", "-preset", "ultrafast", "-tag:v", "hvc1", "-pix_fmt", "yuv420p", "-c:a", "aac", "-shortest",
            "-metadata", "location=+45.7640+004.8357/", "-metadata", "com.apple.quicktime.model=iPhone 15 Pro", "-metadata", "creation_time=2026-11-01T10:00:00Z",
            "-f", "mov",
        ], displayRotation: "90");

    /// <summary>A video filmed in HDR, as recent iPhones do: HEVC 10 bits, BT.2020, HLG.</summary>
    public static Task<string> HlgMov() =>
        Generated("hlg-hevc-10bits.mov",
        [
            "-f", "lavfi", "-i", "testsrc2=size=1280x720:rate=15:duration=2",
            "-vf", "format=yuv420p10le,setparams=color_primaries=bt2020:color_trc=arib-std-b67:colorspace=bt2020nc",
            "-c:v", "libx265", "-preset", "ultrafast", "-pix_fmt", "yuv420p10le", "-tag:v", "hvc1", "-f", "mov",
        ]);

    public static Task<string> WebM() =>
        Generated("vp9.webm", [.. Sources(3, 854, 480), "-c:v", "libvpx-vp9", "-deadline", "realtime", "-cpu-used", "8", "-b:v", "500k", "-c:a", "libopus", "-shortest"]);

    /// <summary>A MP4 of 40 seconds at 100 images per second, tiny: 4000 packets, more than 120 images per second during 31 seconds.</summary>
    public static Task<string> ManyPackets() =>
        Generated("many-packets-100fps-40s.mp4",
            ["-f", "lavfi", "-i", "testsrc2=size=64x64:rate=100:duration=40", "-c:v", "libx264", "-preset", "ultrafast", "-pix_fmt", "yuv420p"]);

    public static Task<string> Gif() => Generated("animated.gif", ["-f", "lavfi", "-i", "testsrc2=size=320x240:rate=10:duration=2"]);

    public static Task<string> Jpeg() => Generated("photo.jpg", ["-f", "lavfi", "-i", "testsrc2=size=1600x1200:rate=1", "-frames:v", "1"]);

    /// <summary>A MP4 of 40 seconds whose header (<c>mvhd</c>) declares 10 seconds.</summary>
    public static async Task<string> LyingMp4()
    {
        var path = Path.Combine(Cache, "lying-40s-says-10s.mp4");
        if (File.Exists(path)) return path;
        var bytes = await File.ReadAllBytesAsync(await Mp4(40, 640, 480));
        var mvhd = bytes.AsSpan().IndexOf("mvhd"u8);
        var timescaleAt = mvhd + 4 + 4 + 8; // version and flags, creation and modification times (version 0)
        var timescale = (bytes[timescaleAt] << 24) | (bytes[timescaleAt + 1] << 16) | (bytes[timescaleAt + 2] << 8) | bytes[timescaleAt + 3];
        var duration = timescale * 10;
        for (var i = 0; i < 4; i++) bytes[timescaleAt + 4 + i] = (byte)(duration >> (24 - (8 * i)));
        await File.WriteAllBytesAsync(path + ".tmp", bytes);
        File.Move(path + ".tmp", path, overwrite: true);
        return path;
    }

    /// <summary>A MP4 whose index is at the end, cut in its middle: the index is lost.</summary>
    public static async Task<string> TruncatedMp4()
    {
        var path = Path.Combine(Cache, "truncated.mp4");
        if (File.Exists(path)) return path;
        var whole = await Generated("index-at-end.mp4", [.. Sources(5, 854, 480), "-c:v", "libx264", "-preset", "ultrafast", "-pix_fmt", "yuv420p"]);
        var bytes = await File.ReadAllBytesAsync(whole);
        await File.WriteAllBytesAsync(path + ".tmp", bytes[..(bytes.Length / 2)]);
        File.Move(path + ".tmp", path, overwrite: true);
        return path;
    }

    /// <summary>What ffprobe reads of a prepared file: its streams and the tags of the container and of the streams.</summary>
    public static async Task<JsonElement> Describe(string path)
    {
        var output = await Run("ffprobe", ["-v", "error", "-show_streams", "-show_format", "-of", "json", path]);
        return JsonDocument.Parse(output).RootElement.Clone();
    }

    private static string[] Sources(double seconds, int width, int height) =>
    [
        "-f", "lavfi", "-i", $"testsrc2=size={width}x{height}:rate=15:duration={seconds.ToString(System.Globalization.CultureInfo.InvariantCulture)}",
        "-f", "lavfi", "-i", $"sine=frequency=440:duration={seconds.ToString(System.Globalization.CultureInfo.InvariantCulture)}",
    ];

    private static async Task<string> Generated(string name, string[] arguments, string? displayRotation = null)
    {
        var path = Path.Combine(Cache, name);
        if (File.Exists(path)) return path;
        await OneAtATime.WaitAsync();
        try
        {
            if (File.Exists(path)) return path;
            Directory.CreateDirectory(Cache);
            var temporary = Path.Combine(Cache, "tmp-" + name);
            await Run("ffmpeg", ["-v", "error", "-y", .. arguments, temporary]);
            if (displayRotation is not null)
            {
                // The mark of a phone filming in portrait: a display matrix, the image itself left in landscape.
                var rotated = Path.Combine(Cache, "rot-" + name);
                await Run("ffmpeg", ["-v", "error", "-y", "-display_rotation", displayRotation, "-i", temporary, "-c", "copy", "-map_metadata", "0", "-f", "mov", rotated]);
                File.Move(rotated, temporary, overwrite: true);
            }

            File.Move(temporary, path, overwrite: true);
            return path;
        }
        finally
        {
            OneAtATime.Release();
        }
    }

    private static async Task<string> Run(string executable, string[] arguments)
    {
        var start = new ProcessStartInfo(executable) { RedirectStandardOutput = true, RedirectStandardError = true, UseShellExecute = false };
        foreach (var argument in arguments) start.ArgumentList.Add(argument);
        using var process = Process.Start(start)!;
        var output = process.StandardOutput.ReadToEndAsync();
        var errors = process.StandardError.ReadToEndAsync();
        await process.WaitForExitAsync();
        if (process.ExitCode != 0) throw new InvalidOperationException($"{executable} {string.Join(' ', arguments)}: {await errors}");
        return await output;
    }

    private static bool Runs(string executable)
    {
        try
        {
            using var process = Process.Start(new ProcessStartInfo(executable, "-version") { RedirectStandardOutput = true, RedirectStandardError = true, UseShellExecute = false });
            if (process is null) return false;
            process.StandardOutput.ReadToEnd();
            process.WaitForExit();
            return process.ExitCode == 0;
        }
        catch (System.ComponentModel.Win32Exception)
        {
            return false;
        }
    }
}
